from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, Field

router = APIRouter(prefix="/api/v1/auth", tags=["auth"])

class LoginRequest(BaseModel):
    username: str = Field(..., min_length=3, max_length=50)
    password: str = Field(..., min_length=8)

@router.post("/login", status_code=status.HTTP_200_OK)
async def login(req: LoginRequest):
    if req.username == "admin" and req.password == "secret123":
        return {"access_token": "jwt_token_sample", "token_type": "bearer"}
    raise HTTPException(status_code=401, detail="Invalid credentials")

import hashlib

def compute_block_hash(block_id: str, prev_hash: str, merkle_root: str, git_sha: str, timestamp: str) -> str:
    payload = f"{block_id}:{prev_hash}:{merkle_root}:{git_sha}:{timestamp}"
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()

def verify_chain(current_block: dict, previous_block: dict) -> bool:
    if current_block.get("prev_hash") != previous_block.get("hash"):
        return False
    recalculated = compute_block_hash(
        current_block["id"],
        current_block["prev_hash"],
        current_block["merkle_root"],
        current_block["git_sha"],
        current_block["timestamp"]
    )
    return recalculated == current_block.get("hash")

from jsonschema import Draft7Validator, SchemaError
from typing import Dict, Tuple, List

def validate_contract_payload(schema: Dict, payload: Dict) -> Tuple[bool, List[str]]:
    validator = Draft7Validator(schema)
    errors = [e.message for e in validator.iter_errors(payload)]
    return (len(errors) == 0, errors)

class WorkflowFSM:
    VALID_TRANSITIONS = {
        "INIT": ["PLANNING", "ABORTED"],
        "PLANNING": ["EXECUTING", "BLOCKED"],
        "EXECUTING": ["VERIFYING", "FAILED"],
        "VERIFYING": ["COMPLETED", "RETRYING"],
        "RETRYING": ["EXECUTING", "FAILED"]
    }
    def __init__(self):
        self.state = "INIT"
    def transition(self, target: str):
        if target not in self.VALID_TRANSITIONS.get(self.state, []):
            raise ValueError(f"Illegal transition from {self.state} to {target}")
        self.state = target

